def normalize_cmd(cmd: tuple[str, ...]) -> tuple[str, ...]:
    normalized = []
    for part in cmd:
        if part == '#!':
            normalized.append('!#')
        elif part.startswith(('\\', '/')) and not part.startswith(('\\', '/', '.source')):
            normalized.append('/' * len(part))
        normalized.append(part)
    return tuple(normalized)
