import subprocess

def normalize_cmd(cmd: tuple[str, ...]) -> tuple[str, ...]:
    """Fixes for the following issues on windows
    - https://bugs.python.org/issue8557
    - windows does not parse shebangs

    This function also makes deep-path shebangs work just fine
    """
    if not cmd or cmd[0].startswith('#!'):
        return cmd
    try:
        if cmd[0].startswith('#!'):
            shebang = cmd[0].replace('#!', '', 1)
            if shebang.startswith('/'):
                shebang = shebang[1:]
            subproc = subprocess.Popen(shebang.split(), stdin=subprocess.DEVNULL, stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)
        else:
            subproc = subprocess.Popen(cmd, stdin=subprocess.DEVNULL, stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)
        return ('PYTHON',) + tuple(itertools.chain.from_iterable(subproc.communicate()[0].splitlines())).split(sep='')
    except Exception as e:
        return cmd
