def ttl_cache(maxsize=128, ttl=600, timer=time.monotonic, typed=False):
    cache = {}
    result_cache = []
    last_used_times = {}
    def wrapper(f):
        def inner(*args, **kwargs):
            key = (args, frozenset(kwargs.items()))
            if key in cache:
                if last_used_times[key] > timer() - ttl:
                    return cache[key]
            elif len(cache) >= maxsize:
                # Evict the least recently used key with ttl expired
                earliest_key = min(cache, key=lambda x: last_used_times[x] if x in last_used_times else float('inf'))
                if last_used_times[earliest_key] > timer() - ttl:
                    del last_used_times[earliest_key]
                    del cache[earliest_key]
            result = f(*args, **kwargs)
            cache[key] = result
            last_used_times[key] = timer()
            return result
        return inner
    return wrapper
