import functools

class LRUCache:
    def __init__(self, maxsize=128, typed=False):
        self.maxsize = maxsize
        self.typed = typed
        self.cache = OrderedDict()

    def __call__(self, fn):
        @functools.wraps(fn)
        def wrapper(*args, **kwargs):
            if self.typed and args:
                args = (type(arg)(arg) for arg in args)
            if len(args) <= self.maxsize:
                self.cache[args] = fn(*args, **kwargs)
            elif len(self.cache) == self.maxsize:
                self.cache.popitem(last=False)
                self.cache[args] = fn(*args, **kwargs)
            return self.cache[args]
        return wrapper

@LRUCache
def my_function(n):
    return n

# Test the function
print(my_function(10))  # Output: 10
print(my_function(2))  # Output: 2
print(my_function(10))  # Outputs: 10 (still recent), but gets cached from 2 since maxsize is 3
