def lfu_cache(maxsize=128, typed=False):
    cache = {}
    count = {}

    def memoized_func(*args):
        if args in cache:
            old_count = count[args]
            new_count = old_count + 1
            if new_count > maxsize:
                for _ in range(maxsize - old_count):
                    arg_to_evict = min(count, key=count.get)
                    count.pop(arg_to_evict)
                    cache.pop(arg_to_evict)
            count[args] = new_count
            return cache[args]
        else:
            count[args] = 1
            return cache[args]

    return memoized_func
