@lru_cache(maxsize=maxsize)
def lfu_cache(maxsize=128, typed=False):
    def decorator(func):
        cache = {}
        def wrapper(*args, **kwargs):
            key = (args, tuple(sorted(kwargs.items())))
            if key in cache:
                # Check if function was typed or not
                if typed and not isinstance(key[0], tuple):
                    cache[key] = func(key[0], **key[1])
                    cache[key] = (cache[key], 1)
                else:
                    cache[key] = func(*args, **kwargs)
                    cache[key] = (cache[key], 1)
            else:
                cache[key] = func(*args, **kwargs)
                cache[key] = (cache[key], 1)
            # Decrement the frequency
            if key in cache:
                cache[key] = (cache[key][0], cache[key][1] - 1)
            # Discard if the frequency is 0
            if key in cache and cache[key][1] == 0:
                del cache[key]
            # Update the cache if the size has been increased
            if len(cache) > maxsize:
                least_freq_key = min(cache, key=lambda x: cache[x][1])
                del cache[least_freq_key]
            return cache[key][0]
        return wrapper
    return decorator
