def cachedmethod(cache, key=hashkey, lock=None):
    def decorator(func):
        @functools.wraps(func)
        def wrapped(*args, **kwargs):
            # Check if the result is already in the cache
            if key in cache:
                return cache[key]

            # Use lock to ensure thread safety
            if lock is not None:
                with lock.acquire():
                    # Check the result again (re-entry check) to avoid race conditions
                    if key in cache:
                        return cache[key]

            # Call the original function and store the result in the cache
            result = func(*args, **kwargs)
            cache[key] = result

            # Release the lock (if used)
            if lock is not None:
                lock.release()

            return result
        return wrapped
    return decorator
