@classmethod
def extostr(cls, e, max_level=30, max_path_level=5):
    stack = []
    exception_strings = []

    def path_print(max_depth, depth):
        if depth > max_depth:
            return
        if depth == max_depth:
            exception_strings.append(str(e))
            return
        for i in range(len(e.with_traceback())):
            path_print(max_depth, depth + 1)

    try:
        if max_level < 1:
            raise ValueError("Maximum level must be greater than 0.")
        if max_path_level < 0:
            raise ValueError("Maximum path level must be non-negative.")
        stack.append((e, 0))
        while stack:
            e, depth = stack.pop()
            def get_exception_string(e):
                cause = e.__cause__
                if cause:
                    return f"{e}: {get_exception_string(cause)}"
                return str(e)

            exception_strings.append(get_exception_string(e))
            if debug and depth + 1 <= max_path_level:
                stack.append((cause, depth + 1) if cause elseNone)
            elif depth < max_level:
                for frame in reversed(e.__traceback__):
                    if frame in stack:
                        break
                    stack.append((frame, depth + 1))

    except Exception as e:
        exception_strings.append(str(e))

    return '\n'.join(exception_strings)
