def _legacy_mergeOrderings(orderings: List[List]) -> List:
    temp_dict = {i: [0] for i in range(len(orderings))}

    for i in range(len(orderings)):
        for item in range(len(orderings[i])):
            temp_dict[i][item] = len(orderings[i]) - searching(item, temp_dict[i], item)

    ordering = []
    for index in sorted(temp_dict.items(), key=lambda x: -x[1][0]):
        ordering.extend(index[1][1:])

    return ordering


def searching(item: int, current_list: List[int], count: int) -> int:
    if current_list[item] < count:
        count += temp_dict[item][current_list[item] + 1]
        current_list[item] += 1
        return searching(item, current_list, count)
    else:
        return count


