import re

class ValidationError(Exception):
    def __init__(self, messages):
        self.messages = messages

def _validate_labels(labels):
    """Check that keys and values in the given labels match against their corresponding
    regular expressions.

    Args:
        labels (dict): the different labels to validate.

    Raises:
        ValidationError: if any of the keys and labels does not match their respective
            regular expression. The error contains as message the list of all errors
            which occurred in the labels. Each element of the list is a dictionary with
            one key-value pair:
            - key: the label key or label value for which an error occurred as string.
            - value: the error message.

            .. code:: python

                # Example:
                labels = {
                    "key1": "valid",
                    "key2": ["invalid"],
                    "$$": "invalid",
                    True: True,
                }
                try:
                    _validate_labels(labels)
                except ValidationError as err:
                    assert err.messages == [
                        {"['invalid']": 'expected string or bytes-like object'},
                        {'$$': "Label key '$$' does not match the regex [...]"},
                        {'True': 'expected string or bytes-like object'},
                        {'True': 'expected string or bytes-like object'},
                    ]
    """
    regex_keys = {
        "key1": r"^[a-z0-9_]+$",
        "key2": r"^[a-z0-9_]+$",
        "$$": r"^[a-z0-9_]+$",
    }
    regex_values = {
        "key1": r"^[a-zA-Z0-9_]+$",
        "key2": r"^[a-zA-Z0-9_]+$",
        "$$": r"^[a-z0-9_]+$",
        True: r"^[a-zA-Z0-9_]+$",
    }

    errorsMessages = []
    for key, value in labels.items():
        if key not in regex_keys:
            errorsMessages.append({"key": key, "value": "key does not have a defined regex pattern"})
        else:
            if not re.match(regex_keys[key], key):
                errorsMessages.append({"key": key, "value": f"Label key '{key}' does not match the regex pattern {regex_keys[key]}"})
        if value is not None and isinstance(value, str):
            if isinstance(regex_values[key], list):
                if not any(value == regex Pattern for regex Pattern in regex_values[key]):
                    errorsMessages.append({"key": key, "value": f"Expected string or bytes-like object, but found {type(value)} and value: {value}"})
            else:
                if not re.match(regex_values[key], value):
                    errorsMessages.append({"key": key, "value": f"Expected string or bytes-like object, but found {type(value)} and value: {value}"})

    if errorsMessages:
        raise ValidationError(errorsMessages)
