        if not isinstance(label, str) or not isinstance(value, str):
            validation_errors.append({"[{}]".format(label): 'expected string or bytes-like object'})
            continue

        if label.startswith("$$"):
            # Regex regexes[label] matches the '$$' key
            if not regexes[label].fullmatch(value):
                validation_errors.append({"[{}]".format(label): regexes[label]})
                continue
        elif label not in regexes or not regexes[label].fullmatch(value):
            validation_errors.append({"[{}]".format(label): regexes[label]})

    if validation_errors:
        raise ValidationError(validation_errors)
