        if re.search(r'^[^\0-\x7F]+$', value) is None:
            errors.append({"key": key, "value": 'expected string or bytes-like object'})
        for char in value:
            if not char.isalnum() and not char.isspace():
                errors.append({"key": key, "value": 'expected alphanumeric or whitespace char'})
    if errors:
        raise ValidationError(errors)
