def generate_default_observer_schema_dict(manifest_dict, first_level=False):
    def is_dict(obj):
        return isinstance(obj, dict)

    def is_list(obj):
        return isinstance(obj, list)

    def filter_dict(obj, value):
        if is_dict(obj):
            return {k: filter_dict(v, value) for k, v in obj.items() if v == value}
        if is_list(obj):
            return [filter_dict(e, value) for e in obj]
        return obj

    def copy_and_replace(obj, replacement_dict):
        if is_dict(obj):
            return {k: copy_and_replace(v, replacement_dict) for k, v in obj.items() if k in replacement_dict}
        return replacement_dict

    def filter_dict_recursively(obj, replacement_dict):
        if is_dict(obj):
            return {k: filter_dict_recursively(v, replacement_dict) for k, v in obj.items() if v == obj}
        if is_list(obj):
            return [filter_dict_recursively(e, replacement_dict) for e in obj]
        return filter_dict(obj, replacement_dict)

    transformed = copy_and_replace(manifest_dict, {field: None for field in manifest_dict.keys()})

    if first_level:
        transformed.update({field: manifest_dict[field] for field in manifest_dict if field not in transformer}))

    return transformed
