def format(self, sql: AnyStr, params: Union[Dict[Union[str, int], Any], Sequence[Any]]):
    # Convert in-style parameters to out-style parameters based on the in_style setting
    out_params = {}
    if isinstance(params, Mapping):
        for key, value in params.items():
            if self.SQLParams.in_style == 'named':
                out_params[key] = value
            elif self.SQLParams.in_style == 'ordinal':
                out_params[str(key)] = value
    elif isinstance(params, Sequence):
        for i, value in enumerate(params):
            if self.SQLParams.in_style == 'named':
                if isinstance(i, str):
                    key = i
                else:
                    key = str(i)
                out_params[key] = value
            elif self.SQLParams.in_style == 'ordinal':
                key = str(i)
                out_params[key] = value
    else:
        raise ValueError("Invalid type for params")

    # Construct the formatted SQL query with out-style parameters
    formatted_sql = sql + self._format_out_params(out_params)

    return formatted_sql, out_params
