def formatmany(
    self,
    sql: AnyStr,
    many_params: Union[abc.Iterable[abc.Mapping[Union[str, int], Any]], abc.Iterable[abc.Sequence[Any]]],
) -> Tuple[AnyStr, Union[abc.List[abc.Mapping[Union[str, int], Any]], abc.List[abc.Sequence[Any]]]]:
    formatted_sql = sql
    converted_params = []

    for params in many_params:
        converted_param = {}
        if self.SQLParams.in_style == 'named':
            if not isinstance(params, abc.Mapping):
                raise ValueError("Input params must be a mapping for named parameter style")
            converted_param = {k: params[k] for k in self.SQLParams.in_style_params}
        elif self.SQLParams.in_style == 'ordinal':
            if not isinstance(params, abc.Sequence):
                raise ValueError("Input params must be a sequence for ordinal parameter style")
            converted_param = params
        else:
            raise ValueError("Invalid in-style provided")

        formatted_param_values = []
        adjusted_param_values = []
        for key, value in converted_param.items():
            if isinstance(value, abc.Sequence):
                adjusted_param_values.extend(value)
                if self.SQLParams.mode == 'retain':
                    formatted_param_values.extend(value)
            else:
                formatted_param_values.append(value)
                adjusted_param_values.append(value)

        formatted_sql = formatted_sql.replace(within=self.SQLParams.varname_prefix, value="{name}").format(name=key)
        formatted_sql = formatted_sql.replace(within=self.SQLParams.in_style_delim, value=value)

        converted_params.append({key: value for key, value in converted_param.items()})

    return formatted_sql, converted_params
