import re

def formatmany(
    self,
    sql: str,
    many_params: Union[Iterable[Dict[str, Any]], Iterable[Sequence[Any]]],
) -> Tuple[str, Union[List[Dict[str, Any]], List[Sequence[Any]]]]:
    serialized_sql = self._sanitize_sql(sql)

    out_params = [[name for name in sqlPattern.group(1)]
                   for sqlPattern in re.finditer(re.compile(r'(?:(?:\$\{)|(?:\?)', flags=re.DOTALL))]

    def replace(param: Any, index: int) -> str:
        if isinstance(param, dict):
            if self.SQLParams.in_style in ('named', 'namedlookup'):
                value = self._escape_dict(param)
            else:
                value = param.popitem()
            return f'@{out_params[index]}' + value
        elif isinstance(param, list):
            value = ",".join([replace(p, index) for p in param])
            return f'@{out_params[index]}' + value
        else:
            return str(param)

    new_sql = re.sub(r'\$(\d+)', replace, serialized_sql)

    new_params = []
    for idx, params in enumerate(many_params):
        if self.SQLParams.in_style in ('named', 'namedlookup'):
            out_params[idx] = '{}'
        else:
            out_params[idx] = '{}'
        new_params.append(eval("{" + ",".join(out_params[idx]) + "}"))

    return new_sql.encode('utf-8'), new_params
