def pretty(self, indent=0, debug=False):
    """
    Return a pretty formatted representation of self.
    """
    result = "-- self\n"
    for key, value in self.__dict__.items():
        if debug or not key.startswith("__"):
            result += f"  {key}: {self._format_value(key, value, indent + 2)}\n"
    return result[:-1]

def _format_value(self, key, value, indent):
    if isinstance(value, dict):
        value_str = pretty(value, indent)
    else:
        value_str = f"{repr(value)}"
    return f"{indent * 2}{key}: {value_str}"
```

