    for arg in args:
        if isinstance(arg, (list, tuple)):
            absorbed = self.absorb(arg)
            result.extend(absorbed)
        elif isinstance(arg, bool):
            if arg:
                result.append(arg)
            else:
                result.extend([arg, arg])
        elif isinstance(arg, str):
            if arg == "A":
                result.extend(["A", "A"])
            elif arg == "&":
                result.extend(["A", "A"])
            elif arg == "|":
                result.extend(["A", "A"])
            elif arg == "~A":
