from typing import Any, Callable
from collections import defaultdict

class HookType:
    def __init__(self, name, priority):
        self.name = name
        self.priority = priority

class HookRegistry:
    def __init__(self):
        self.hooks = defaultdict(list)

    def on(self, hook: HookType):
        """Decorator function to add a new handler to the registry.

        Args:
            hook (HookType): Hook attribute for which to register the handler.

        Returns:
            callable: Decorator for registering listeners for the specified
            hook.
        """
        def decorator(func: Callable) -> Callable:
            self.hooks[hook].append(func)
            return func
        return decorator

def call_hooks(hook_name: str, *args, **kwargs):
    registry = HookRegistry()
    for hook in registry.hooks[hook_name]:
        hook(*args, **kwargs}
```

This code defines a `HookType` class to represent the type of a hook and a `HookRegistry` class to manage the registration of handlers for different hooks. The `on` method returns a decorator that adds a new handler to the registry for a specified hook. The `call_hooks` function retrieves all handlers for a specified hook and calls them with the provided arguments.

