def tzname_in_python2(namefunc):
    """Change unicode output into bytestrings in Python 2

    tzname() API changed in Python 3. It used to return bytes, but was changed
    to unicode strings
    """
    # Check if the process is running in Python 2
    import sys
    if sys.version_info[0] == 2:
        # Create a class that handles the Unicode-to-Byte conversion
        class UnicodeToByteConverter:
            def __init__(self):
                pass

            def __call__(self, value):
                # Convert the Unicode string to a byte string
                return value.encode('utf-8')

        # Wrap the original function with the converter
        return UnicodeToByteConverter()
