import os

def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""
    process = subprocess.Popen(commands + list(args), cwd=cwd, stdout=subprocess.PIPE, stderr=subprocess.PIPE, env=env if env else os.environ)
    stdout, stderr = process.communicate()

    if stderr:
        if hide_stderr:
            stderr = b""  # Ignore stderr if hidden
