def validate_hierarchy(self, validate_objects=True, check_digests=True, show_warnings=False):
    """
    Validate storage root hierarchy.

    Returns:
        num_objects - number of objects checked
        good_objects - number of objects checked that were found to be valid
    """
    num_objects = 0
    good_objects = 0

    if validate_objects:
        num_objects += len(self.storage_objects)
        # Perform checks on each object
        for obj in self.storage_objects:
            if obj.is_valid():
                good_objects += 1
            else:
                if show_warnings:
                    print(f"Object {obj.name} is invalid.")

    if check_digests:
        # Calculate digests for each object
        digests = {obj.name: obj.calculate_digest() for obj in self.storage_objects}
        # Compare digests with expected digests
        for name, digest in digests.items():
            if digest != obj.expected_digest:
                if show_warnings:
                    print(f"Digest for {name} does not match expected digest.")

    return num_objects, good_objects
