import ruamel.yaml

def deep_merge_nodes(nodes):
    result = []
    seen_keys = set()

    for key, value in nodes:
        key_node = yaml.nodes.ScalarNode(tag=key.tag, value=key.value)

        if key_node not in seen_keys:
            seen_keys.add(key_node)
            result.append((key_node, value))
        else:
            # Merge with existing value
            node_to_merge = next((val for val in result if val[0].value == key_node.value), None)
            if node_to_merge:
                if isinstance(value, ruamel.yaml.nodes.MappingNode) and isinstance(node_to_merge[1], ruamel.yaml.nodes.MappingNode):
                    node_to_merge[1].update(value[1])
                else:
                    node_to_merge[1] = value

    return [(k, v) for k, v in result]
