def deep_merge_nodes(nodes):
    result = []
    seen_keys = set()
    for node, value in nodes:
        key = node.tag + '-' + str(value)
        if key not in seen_keys:
            seen_keys.add(key)
            result.append((node, value))
        else:
            if not isinstance(value, MappingNode):
                value = MappingNode(tag=node.tag)
            if not isinstance(result[-1][1], MappingNode):
                result.append((result[-1][0], MappingNode(tag=result[-1][1].tag)))
            for k, v in value.items():
                result[-1][1].append((k, v))
    return result
