def parse_arguments(*unparsed_arguments):
    if len(unparsed_arguments) < 1:
        raise ValueError("At least one argument is required.")

    args, parser = parser.parse_known_args(unparsed_arguments)

    result = {}
    if hasattr(args, 'object') and hasattr(args.object, 'subparsers'):
        for name, subparser in args.object.subparsers.choices.items():
            # Check for subparser arguments and add them to the result
            if hasattr(subparser, 'arguments'):
                result[name] = subparser.parse_known_args(subparser.arguments)
            # Check for global arguments and add them to the result
            elif hasattr(parser, 'arguments'):
                result['global'] = parser.parse_known_args(parser.arguments)
    else:
        result['global'] = args

    return result
