def size_to_bytes(size: str) -> int:
    factor = {
        'K': 1024,
        'M': 1e6,
        'G': 1e9,
        'TB': 1e12
    }
    M = len(size) - 1
    size_str = size[:M] + size[M]
    return round(float(size_str) * factor[size[M]])
