    suffix_map = {'B': 1, 'K': 1024, 'M': 1024**2, 'G': 1024**3}
    suffix = size[-1]
    value = float(size[:-1])
    if suffix not in suffix_map:
        raise ValueError("Invalid file size suffix")
    return int(round(value * suffix_map[suffix]))
