import urllib.parse

def _replace_url_args(url, url_args):
    parsed_url = urllib.parse.urlparse(url)
    query_params = parsed_url.query
    parsed_query = urllib.parse.parse_qs(query_params)

    for arg in url_args:
        values = url_args[arg]
        for value in values:
            if arg in parsed_query and value in parsed_query[arg]:
                del parsed_query[arg][value]
            elif value in parsed_query:
                parsed_query[value].append(dir(value))  # Assuming 'dir(value)' retrieves a list of methods
            else:
                parsed_query[arg] = [value]

    new_query_params = urllib.parse.urlencode(parsed_query, encoding='utf-8', quote_via= urllib.parse.quote)

    return urllib.parse.urlunparse((parsed_url.scheme, parsed_url.netloc, parsed_url.path, parsed_url.params, new_query_params, parsed_url.fragment))

```

