def string_to_int(string: str, alphabet: List[str]) -> int:
    converter = {alphabet[i]: i for i in range(len(alphabet))}
    num, digit = 0, len(string) - 1
    while digit >= 0:
        num *= len(alphabet)
        num += converter[string[digit]]
        digit -= 1
    return num
```

