import re

def split(s, platform='this'):
    """Multi-platform variant of shlex.split() for command-line splitting.
    For use with subprocess, for argv injection etc. Using fast REGEX.

    platform: 'this' = auto from current platform;
              1 = POSIX;
              0 = Windows/CMD
              (other values reserved)
    """
    if platform == 'this':
        platforms = {
            'posix': re.compile(r'(["\s]).+?\1'),
            'windows': re.compile(r'(["\s]).+?\1')
        }
        platform = 'posix' if 'win' not in sys.platform else 'windows'
    elif platform == 1:
        platform = 'posix'
    elif platform == 0:
        platform = 'windows'
    else:
        raise ValueError("Invalid platform value. Must be 'this', 1, or 0.")

    return platforms[platform].findall(s)
```

