import re

BEGINNING_WITHEBAR = re.compile('^\\s*(-)?\\|\\s*')
SPLIT_CHAR = re.compile('([-]?\\|\\s+|$)')

def split(s, platform='this'):
    def _convert(input_str):
        if platform in ('this', 1):
            return input_str.replace('|', ' ')
        return input_str.replace('|', '^')

    if platform in ('this', 1):
        split_char.replace('|', ' ').insert(0, '\\s*')
    else:
        split_char.replace('|', '^').insert(0, '\\s*')

    s = _convert(s)
    result = []
    start = 0
    if platform in ('this', 1):
        split_char.insert(0, '|')
    else:
        split_char.insert(0, '^')

    for match in re.finditer(split_char, s, re.MULTILINE):
        if platform in ('this', 1):
            if match.group(0) == '\\s*':
                continue
            if match.start() == 0 and length == s.count('|') + 1:
                result.append('')
                continue
            if length == s.count('|'):
                result.append(s[match.start():])
        else:
            if match.group(0) == '^':
                continue
            if re.match('^[|\\s]*', s[0:match.start()]):
                result.append('')
            if re.match('[|\\s]*', s[match.end()]):
                result.append(s[match.end():])

        if match.group(0) != '|':
            result.append(s[start:match.start()])
        start = match.end()
    result.append(s[start:])
    return result
