def parse_frequency(frequency):
    if frequency is None or frequency == "always":
        return None
    parts = frequency.split()
    if len(parts) != 2:
        raise ValueError(f"Invalid frequency format: {frequency}")
    number, unit = parts
    try:
        number = int(number)
    except ValueError:
        raise ValueError(f"Invalid number in frequency: {number}")
    if unit not in ["hours", "minutes", "seconds", "weeks", "days", "months", "years"]:
        raise ValueError(f"Invalid unit in frequency: {unit}")
    if unit == "hours":
        return datetime.timedelta(hours=number)
    elif unit == "minutes":
        return datetime.timedelta(minutes=number)
    elif unit == "seconds":
        return datetime.timedelta(seconds=number)
    elif unit == "weeks":
        return datetime.timedelta(weeks=number)
    elif unit == "days":
        return datetime.timedelta(days=number)
    elif unit == "months":
        return datetime.timedelta(days=number * 30)
    elif unit == "years":
        return datetime.timedelta(days=number * 365)
