def parse_frequency(frequency):
    try:
        if frequency is None or frequency.lower() == "always":
            return None
        for unit, multiplier in [("months", 30), ("weeks", 7), ("days", 1)]:
            if frequency.endswith(unit):
                return timedelta(**{unit: int(frequency[:-len(unit)].strip()) * multiplier})
        raise ValueError(f"Failed to parse frequency: {frequency}")
    except (ValueError, KeyError) as e:
        raise ValueError(f"Failed to parse frequency: {frequency}. Error: {str(e)}")
```

