def parse_frequency(frequency):
    if frequency is None or frequency == "always":
        return None
    try:
        num, unit = map(int, frequency.split())
        units = {"week": timedelta(weeks=num), "day": timedelta(days=num), "hour": timedelta(hours=num),
                 "minute": timedelta(minutes=num), "second": timedelta(seconds=num)}
        return units[unit]
    except (ValueError, KeyError):
        raise ValueError("Invalid frequency format: {}".format(frequency))
