import re

def make_find_paths(find_paths):
    regex_at = re.compile(r'^@')

    for i, pattern in enumerate(find_paths):
        if regex_at.match(pattern):
            find_paths[i] = pattern[1:]
            while pattern:
                pattern = pattern[0] + '..' + pattern[1:]
        else:
            find_paths[i] = re.escape(pattern)

    return find_paths
