import os

def _resolve_string(matcher):
    if 'env' not in os.environ:
        raise ValueError("No environment 'env'.")

    name, default = matcher.split('=')
    name = name.strip()
    default = default.strip() if default else None

    if name in os.environ:
        return os.environ[name]
    elif default:
        return default
    else:
        raise ValueError(f"No environment variable '{name}'. Default value '{default}' not provided.")
