from typing import Set, Optional

def find_roots(
    graph: rdflib.Graph, prop: rdflib.URIRef, roots: Optional[Set["Node"]] = None
) -> Set["Node"]:
    if roots is None:
        roots = set()

    for child in graph.subjects(prop, None):
        if child not in roots:
            if child.ancestors(prop, graph).max_depth() == len(roots):
                roots.add(child)

    return roots
