from typing import Set, Optional

def find_roots(
    graph: "Graph", prop: "URIRef", roots: Optional[Set["Node"]] = None
) -> Set["Node"]:
    if roots is None:
        roots = set()

    for child, _, parent in graph:
        if child.is_a(prop) and parent not in roots:
            roots.add(parent)
            roots.update(find_roots(graph, prop, roots))

    return roots
```

