def _dump_string(obj, dumper=None):
    _special_map = {
        'utf-8': {u"\u2028": "\n"},  # Unicode soft hyphen
        'utf-16': {u"\u2028": u"\uFEFF", u"\u2029": u"\u2029"},  # Windows Unicode BOM
        'utf-32': {u"\u2028": u"\uFEFF\uFEFF\uFEFF", u"\u2029": u"\uFEFF\uFEFF\uFEFF"},  # Windows Unicode BOMs
        'iso8859_1': {'\u00ad': u'-'},  # Soft Hyphen
        'latin-1': {'\u00ad': '-'},  # Soft Hyphen
    }
    if dumper is None:
        from yaml.representer import SafeDumper
        dumper = SafeDumper
    try:
        # Dump to a py2-unicode string
        stream = StringIO()
        dumper.represent(data, stream)
        return stream.getvalue().decode('utf-8')
    except UnicodeEncodeError as e:
        # Dump to a py3-string, with special handling for certain characters
        parts = []
        for index_needed, char in enumerate(obj):
            if char in {'\r', '\n', '\t', "'"} or \
                    char in _special_map[dumper.settings['encoding']].keys():
                if index_needed > 0:
                    parts.append(parts.pop())
                parts.extend(["'", dumper.representUnicode(char), "'"])
        parts = [''.join(parts)]
        return ''.join(parts).encode('utf-8')
```

