def _verify(iface, candidate, tentative=False, vtype=None):
    from zope.interface import Invalid, implementedBy, provider
    try:
        if not tentative and not implementedBy(candidate, iface):
            raise Invalid(f"{candidate} does not implement the interface {iface}")
        iface.check.implementedBy(candidate)
        iface.check.providedBy(candidate)
        iface.check.requiredMethods(candidate)
        iface.check.requiredAttributes(candidate)
        return True
    except Invalid as e:
        errors = [str(e)]
        for method, error in iface.check erroneousMethods(candidate):
            errors.append(f"Method {method}: {error}")
        for attribute, error in iface.check erroneousAttributes(candidate):
            errors.append(f"Attribute {attribute}: {error}")
        raise Invalid("\n".join(errors))
