    # Ensure candidate claims iface provides it
    if iface.providedBy(candidate):
        if tentative:
            return True
        all_missing_methods = iface.allMethods()
        candidate_methods = candidate.declaredMethods()
        missing_methods = all_missing_methods - candidate_methods
        if missing_methods:
            raise zope.interface.Invalid(f"candidate does not define methods: {missing_methods}")
