    if not tentative:
        try:
            provided_methods = iface.providedBy(candidate)
        except AttributeError:
            provided_methods = []
        if provided_methods != iface.implemented():
            errors.append(Invalid(f"Candidate does not provide the interface. Expected {iface.implemented()}, but provided {provided_methods}."))

