    # Check that the candidate defines all necessary attributes
    for name, attribute in iface.attributes():
        if hasattr(candidate, name):
            errors.append(Invalid(f"Attribute '{name}' already defined in the candidate."))

    if errors:
        if len(errors) == 1:
            raise errors[0]
        raise Invalid("\n".join(str(e) for e in errors))
    else:
        return True
