from datetime import datetime, timezone
import re

class ISOParser:
    def isoparse(self, dt_str):
        formats = {
            "common": {
                r"(\d{4})(-(0?[1-9]|1[0-2]))?(-(0?[1-9]|[1-2]\d){1,2})?(\+([0-9][0-9]|1[0-2]):[0-5][0-9]){0,2}?$": lambda parts: datetime(int(parts[0]), int(parts[1] or 1), int(parts[2] or 1), tzinfo=timezone.utc if parts[3] == "Z" else timezone.strptime(parts[3], "+%H:%M" if len(parts) > 4 else "+%H%M"))
            },
            "uncommon": {
                r"(\d{4})(-(0?[1-9]|1[0-2]))?(-(0?[1-9]|[1-2]\d){1,2})?(\+([0-9][0-9]|1[0-2]):[0-5][0-9])?(\+([0-9]{1,2}):[0-5][0-9])?(\+([0-9]{2}))?$": lambda parts: datetime(int(parts[0]), int(parts[1] or 1), int(parts[2] or 1), tzinfo=timezone.utc if parts[3] == "Z" else timezone.strptime(parts[3], "+%H:%M" if len(parts) > 4 else "+%H%M"))
            }
        }

        for key, value in formats.items():
            regex = value.get(key)
            match = re.match(regex, dt_str)
            if match:
                return value[key](match.groups())

        raise ValueError(f"Invalid ISO-8601 string: {dt_str}")
