import re
from typing import Tuple, Set

def find_tags(text: str, replacer: callable = None) -> Tuple[Set, str]:
    # Create a regular expression pattern to find tags
    tag_pattern = re.compile(r'<([^>]+)>', re.IGNORECASE)
    tags = {match.group(1).lower() for match in tag_pattern.finditer(text)}

    # If a replacer function is provided, apply it to each tag
    if replacer:
        tags = {replacer(tag).lower() for tag in tags}

    return tags, text
