def _get_conditionally_required_args(self, command_name, options_spec,
                                         args):
    """List arguments with ``required_when`` condition matched.

    :param command_name: the command name.
    :param options_spec:  the list of command spec options.
    :param args: the received input arguments
    :return: list, list of argument names with matched ``required_when``
            condition
    """
    allowed_args = {}
    for option_spec in options_spec:
        arg_name = option_spec.get('name')
        if arg_name is None:
            continue
        if arg_spec.get('required_when') is not None:
            if arg_spec['required_when'] in allowed_args:
                allowed_args[arg_spec['required_when']].append(arg_name)
            else:
                allowed_args[arg_spec['required_when']] = [arg_name]

    result = []
    for arg_name in args:
        condition = None
        for required_when, required_args in allowed_args.items():
            if arg_name in required_args:
                condition = required_when
                break
        if condition is not None:
            result.append((arg_name, condition))

    return result
```

