def get_plugin_spec_flatten_dict(plugin_dir):
    spec = {}
    for root, dirs, files in os.walk(plugin_dir):
        for file in files:
            if file.endswith('.json'):
                file_path = os.path.join(root, file)
                plugin_props = json.load(open(file_path))
                for key, val in plugin_props.items():
                    if key in spec:
                        if isinstance(spec[key], list):
                            spec[key].append(val)
                        else:
                            spec[key] = [spec[key], val]
                    else:
                        spec[key] = val
    return spec
```

